const opportunity = $('Score opportunities').item.json;
const content = $input.first().json.choices?.[0]?.message?.content || 'No draft returned. Review the opportunity manually.';
return [{ json: { to: opportunity.reviewEmail, subject: `[Review] ${opportunity.title}`, message: [`Human review required - nothing was sent automatically.`, ``, `Score: ${opportunity.score}/100`, `Reasons: ${opportunity.scoreReasons.join(', ') || 'none'}`, ``, `Draft:`, content, ``, `Source: ${opportunity.url}`, ``, `Review the listing and edit the draft before sending.`].join('\n') } }];
